  const handleAddUltrasonicInspection = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const nominalT = Number(formData.get('nominalT')) || 5.3;
    const minT = Number(formData.get('minT')) || 5.35;
    const maxT = Number(formData.get('maxT')) || 5.65;
    const eccentricity = Number(formData.get('eccentricity')) || 4.5;
    const ovalityPassed = formData.get('ovalityPassed') === 'yes';

    const isThicknessInTolerance = minT >= nominalT && eccentricity <= 8.0;
    const isBlocked = !isThicknessInTolerance || !ovalityPassed;
    const clearanceStatus = isBlocked ? 'BLOCKED_NON_STANDARD' : 'APPROVED_FOR_PACKAGING';

    let rejectionReason: string | null = null;
    if (isBlocked) {
      const reasons: string[] = [];
      if (minT < nominalT) reasons.push(`Min wall ${minT}mm < nominal ${nominalT}mm`);
      if (eccentricity > 8.0) reasons.push(`Eccentricity ${eccentricity}% exceeds 8% ceiling`);
      if (!ovalityPassed) reasons.push('Outer diameter ovality failed gauge');
      rejectionReason = reasons.join('; ');
    }

    const newInsp: PipeUltrasonicInspectionRecord = {
      id: `pui-${Date.now()}`,
      inspectionCode: `UT-INSP-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
      batchNumber: String(formData.get('batchNumber') || 'BATCH-PVC-110-NEW').toUpperCase(),
      pipeDiameterMm: Number(formData.get('diameter')) || 110.0,
      nominalThicknessMm: nominalT,
      minMeasuredThicknessMm: minT,
      maxMeasuredThicknessMm: maxT,
      wallEccentricityPercent: eccentricity,
      outerDiameterMeasuredMm: Number(formData.get('outerD')) || 110.2,
      pipeLengthMeters: Number(formData.get('pipeLength')) || 6.0,
      ovalityTolerancePassed: ovalityPassed,
      isWallThicknessInTolerance: isThicknessInTolerance,
      packagingBlocked: isBlocked,
      clearanceStatus,
      rejectionReason,
      inspectionNotes: String(formData.get('notes') || (isBlocked ? 'Quarantined from packaging bundle.' : 'Concentricity verified.')),
      inspectorId: 'wall.thickness@apexmanufacturing.com',
      createdAt: 'Just now',
    };

    setUltrasonicInspections([newInsp, ...ultrasonicInspections]);
    setIsNewUltrasonicModal(false);
    if (isBlocked) {
      showToast(`DISPATCH GATE LOCKED: Batch ${newInsp.batchNumber} BLOCKED from packaging!`);
    } else {
      showToast(`Ultrasonic inspection ${newInsp.inspectionCode} PASSED. Lot approved for bundling.`);
    }
  };

  const handleTogglePackagingGate = (inspectionId: string, unblock: boolean) => {
    setUltrasonicInspections(
      ultrasonicInspections.map((insp) => {
        if (insp.id === inspectionId) {
          return {
            ...insp,
            packagingBlocked: !unblock,
            clearanceStatus: unblock ? 'CONDITIONAL_ACCEPTANCE' : 'BLOCKED_NON_STANDARD',
          };
        }
        return insp;
      }),
    );
    showToast(unblock ? 'Packaging gate override: Lot conditionally accepted.' : 'Packaging gate locked: Lot quarantined.');
  };

  const handleAddHydrostaticTest = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const targetP = Number(formData.get('targetPressure')) || 32.0;
    const achievedP = Number(formData.get('achievedPressure')) || 38.0;
    const isPassed = achievedP >= targetP;
    const hoopStress = Number(((achievedP * 110) / (2 * 5.3 * 10)).toFixed(2));
    const certNumber = `HYD-CERT-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`;

    const newTest: HydrostaticBurstTestRecord = {
      id: `hbt-${Date.now()}`,
      certificateNumber: certNumber,
      testSampleBarcode: String(formData.get('barcode') || `SMP-PIPE-${Math.floor(100 + Math.random() * 900)}`),
      pipeSpecification: String(formData.get('specification') || 'PVC-U 110mm PN10 SDR21 (IS 4985:2021)'),
      testType: String(formData.get('testType') || 'BURST_PRESSURE_DESTRUCTIVE'),
      targetTestPressureBar: targetP,
      achievedBurstPressureBar: achievedP,
      testDurationHours: Number(formData.get('durationHours')) || 1.0,
      waterBathTempCelsius: Number(formData.get('bathTemp')) || 20.0,
      calculatedHoopStressMpa: hoopStress,
      failureMode: String(formData.get('failureMode') || (isPassed ? 'DUCTILE_BURST' : 'BRITTLE_SLIT')) as any,
      complianceStatus: isPassed ? 'PASSED_COMPLIANT' : 'FAILED_BURST_UNDER_SPEC',
      complianceCertificateIssued: isPassed,
      certifiedByRole: 'HYDROSTATIC_BURST_TESTING_MANAGER',
      destructiveTestNotes: String(formData.get('notes') || `Achieved ${achievedP} bar (target ${targetP} bar). Ductile rupture verified.`),
      createdAt: 'Just now',
    };

    setHydrostaticTests([newTest, ...hydrostaticTests]);
    setIsNewHydrostaticModal(false);
    if (isPassed) {
      showToast(`Hydrostatic test passed! Pressure Certificate ${certNumber} issued.`);
    } else {
      showToast(`Hydrostatic test FAILED: Burst pressure under specification!`);
    }
  };

