  const handleUpdateKanbanStatus = (
    id: string,
    status: 'TRIGGERED' | 'EN_ROUTE' | 'DELIVERED_LINE_SIDE' | 'CONSUMED' | 'DEPLETED',
    deliveredQty?: number,
  ) => {
    setKanbanSignals(
      kanbanSignals.map((sig) => {
        if (sig.id === id) {
          return {
            ...sig,
            kanbanStatus: status,
            deliveredQuantity: deliveredQty !== undefined ? deliveredQty : (status === 'DELIVERED_LINE_SIDE' ? sig.requiredQuantity : sig.deliveredQuantity),
            actualDeliveryTimestamp: status === 'DELIVERED_LINE_SIDE' ? 'Just now' : sig.actualDeliveryTimestamp,
          };
        }
        return sig;
      }),
    );
    showToast(`Kanban signal status updated to ${status}.`);
  };

