  const handleAddTestingRecord = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const voltage = Number(formData.get('voltage')) || 3.3;
    const current = Number(formData.get('current')) || 140.0;
    const freq = Number(formData.get('freq')) || 48.0;
    const isCalibrated = formData.get('isCalibrated') === 'yes';

    // Strict validation: instrument calibration lock
    const isPassed = isCalibrated && voltage >= 3.15 && voltage <= 3.45 && current <= 180.0;
    let testResult: any = 'PASSED';
    let defectLog: string | null = null;

    if (!isCalibrated) {
      testResult = 'BLOCKED_UNCALIBRATED';
      defectLog = 'DISPATCH BLOCKED: Test rig calibration expired! Recalibration required before testing.';
    } else if (!isPassed) {
      testResult = 'FAILED';
      defectLog = current > 180.0 ? `Excess quiescent current ${current}mA exceeds 180mA limit.` : 'Voltage out of tolerance window.';
    }

    const coaNumber = testResult === 'PASSED' ? `COA-ELEC-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}` : null;

    const newTest: ElectricalTestingItemRecord = {
      id: `etr-${Date.now()}`,
      testReportNumber: `ETR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`,
      pcbOrDeviceSerial: String(formData.get('serial') || `SN-HW-${Math.floor(10000 + Math.random() * 90000)}`).toUpperCase(),
      testRigId: String(formData.get('rigId') || 'Automated ICT Rig Keysight i3070'),
      voltageRangeVolts: voltage,
      currentConsumptionMilliAmps: current,
      frequencyMhz: freq,
      instrumentCalibrationCertId: String(formData.get('calCert') || 'CAL-NABL-2026-8812'),
      calibrationCertValidUntil: String(formData.get('calExpiry') || '2027-05-18'),
      isInstrumentCalibrated: isCalibrated,
      testResult,
      defectLog,
      clearanceCertificateNumber: coaNumber,
      certifiedAt: testResult === 'PASSED' ? 'Just now' : null,
      notes: String(formData.get('notes') || (testResult === 'PASSED' ? 'Automated ICT/FCT functional test passed.' : defectLog)),
      createdAt: 'Just now',
    };

    setElectricalTests([newTest, ...electricalTests]);
    setIsNewTestingModal(false);
    if (testResult === 'PASSED') {
      showToast(`Test passed! Clearance Certificate ${coaNumber} issued.`);
    } else {
      showToast(`TEST GATE LOCKED: Device ${newTest.pcbOrDeviceSerial} flagged as ${testResult}!`);
    }
  };

