  const handleAddHvTest = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const isCalibrated = formData.get('isCalibrated') === 'yes';
    const appliedKv = Number(formData.get('appliedKv')) || 70.0;
    const pd = Number(formData.get('partialDischarge')) || 4.5;
    const ir = Number(formData.get('irGohms')) || 40.0;
    const ratioDev = Number(formData.get('ratioDev')) || 0.12;

    const pdPassed = pd <= 10.0;
    let testResult: 'PASSED' | 'FAILED' | 'BLOCKED_UNCALIBRATED' | 'HIGH_PARTIAL_DISCHARGE' = 'PASSED';
    let dispatchBlocked = false;

    if (!isCalibrated) {
      testResult = 'BLOCKED_UNCALIBRATED';
      dispatchBlocked = true;
    } else if (!pdPassed) {
      testResult = 'HIGH_PARTIAL_DISCHARGE';
      dispatchBlocked = true;
    } else if (ratioDev > 0.5 || ir < 10.0) {
      testResult = 'FAILED';
      dispatchBlocked = true;
    }

    const certNumber = testResult === 'PASSED' ? `CERT-HVT-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}` : null;

    const newTest: HvRoutineTestItemRecord = {
      id: `hvt-${Date.now()}`,
      testReportCode: `HVT-REP-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
      equipmentSerialNumber: String(formData.get('equipmentSerial') || `SN-EQP-${Math.floor(1000 + Math.random() * 9000)}`).toUpperCase(),
      equipmentType: String(formData.get('equipmentType') || 'POWER_TRANSFORMER'),
      ratedKvaOrMva: String(formData.get('ratedKva') || '2500 kVA'),
      ratedVoltageKv: String(formData.get('ratedVoltage') || '33/11 kV'),
      automatedTestRigId: String(formData.get('rigId') || 'Automated HV Test Rig Phenix BK-130'),
      rigCalibrationCertId: String(formData.get('calCert') || 'CAL-NABL-RIG-2026-44'),
      rigCalibrationValidUntil: String(formData.get('calExpiry') || '2027-06-15'),
      isRigCalibrated: isCalibrated,
      appliedHvWithstandKv: appliedKv,
      hvWithstandDurationSeconds: Number(formData.get('durationSeconds')) || 60,
      hvWithstandPassed: true,
      measuredPartialDischargePc: pd,
      pdTolerancePassed: pdPassed,
      insulationResistanceGohms: ir,
      windingResistanceRPhaseOhms: Number(formData.get('wR')) || 0.420,
      windingResistanceYPhaseOhms: Number(formData.get('wY')) || 0.421,
      windingResistanceBPhaseOhms: Number(formData.get('wB')) || 0.419,
      turnsRatioDeviationPct: ratioDev,
      overallTestResult: testResult,
      dispatchBlocked,
      testCertificateNumber: certNumber,
      certifiedAt: testResult === 'PASSED' ? 'Just now' : null,
      testedByManager: 'HV_ROUTINE_TESTING_MANAGER',
      notes: String(formData.get('notes') || (testResult === 'PASSED' ? 'Dielectric withstand, ratio and partial discharge verified compliant.' : 'Unit blocked from dispatch!')),
      createdAt: 'Just now',
    };

    setHvTests([newTest, ...hvTests]);
    setIsNewHvTestModal(false);
    if (testResult === 'PASSED') {
      showToast(`HV Routine Test PASSED! Calibration & Test Certificate ${certNumber} auto-generated.`);
    } else {
      showToast(`DISPATCH LOCKOUT ACTIVATED: Equipment ${newTest.equipmentSerialNumber} failed statutory test (${testResult})!`);
    }
  };

  const handleCertifyHvTest = (id: string) => {
    const certNumber = `CERT-HVT-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;
    setHvTests(
      hvTests.map((t) => {
        if (t.id === id) {
          return {
            ...t,
            overallTestResult: 'PASSED',
            dispatchBlocked: false,
            isRigCalibrated: true,
            pdTolerancePassed: true,
            testCertificateNumber: certNumber,
            certifiedAt: 'Just now',
          };
        }
        return t;
      }),
    );
    showToast(`Test & Calibration Certificate ${certNumber} issued & signed! Dispatch unlocked.`);
  };

