  const handleAddSparkTest = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const faults = Number(formData.get('faultCount')) || 0;
    const dcResistance = Number(formData.get('dcResistance')) || 0.264;
    const maxResistance = Number(formData.get('maxResistance')) || 0.268;
    const encoderOk = formData.get('encoderOk') === 'yes';

    const isDcOk = dcResistance <= maxResistance;
    const isPassed = faults === 0 && isDcOk && encoderOk;
    const certNumber = isPassed ? `QC-CERT-CBL-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}` : `QUARANTINE-${Math.floor(1000 + Math.random() * 9000)}`;

    const newTest: HvSparkTestingRecord = {
      id: `spk-${Date.now()}`,
      certificateNumber: certNumber,
      cableDrumNumber: String(formData.get('drumNumber') || `DRUM-CBL-${Math.floor(1000 + Math.random() * 9000)}`).toUpperCase(),
      cableTypeAndSize: String(formData.get('cableType') || '3C x 70 sq mm 11 kV XLPE Armoured'),
      lengthMeters: Number(formData.get('lengthMeters')) || 1000,
      testVoltageKv: Number(formData.get('testVoltageKv')) || 18.0,
      sparkFaultCount: faults,
      faultPositionsJson: faults > 0 ? JSON.stringify([{ positionMeters: Math.floor(Math.random() * 400 + 100), voltage: Number(formData.get('testVoltageKv')) || 18.0 }]) : '[]',
      conductorDcResistanceOhmsPerKm: dcResistance,
      maxPermissibleResistance: maxResistance,
      isDcResistancePassed: isDcOk,
      meterMarkingStartM: 0,
      meterMarkingEndM: Number(formData.get('lengthMeters')) || 1000,
      encoderCalibrationValid: encoderOk,
      qualityClearanceIssued: isPassed,
      dispatchBlocked: !isPassed,
      certifiedByManager: 'HV_SPARK_TESTING_QA_MANAGER',
      certifiedAt: isPassed ? 'Just now' : null,
      remarks: String(formData.get('remarks') || (isPassed ? 'Zero spark faults & conductor DC resistance verified compliant.' : 'DISPATCH BLOCKED: Quality gate lockout active due to test failure!')),
      createdAt: 'Just now',
    };

    setSparkTests([newTest, ...sparkTests]);
    setIsNewSparkModal(false);
    if (isPassed) {
      showToast(`Spark QA Test PASSED! Quality Clearance Certificate ${certNumber} auto-generated.`);
    } else {
      showToast(`DISPATCH BLOCKED: Drum ${newTest.cableDrumNumber} failed spark QA or DC resistance check!`);
    }
  };

