  const handleAddFabricInspection = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const points = Number(formData.get('pointsPer100SqYards')) || 16.5;
    const maxPoints = Number(formData.get('maxPermissiblePoints')) || 28.0;
    const warpShrink = Number(formData.get('warpShrinkagePct')) || 2.2;
    const weftShrink = Number(formData.get('weftShrinkagePct')) || 1.9;

    const isPointsPassed = points <= maxPoints;
    const isShrinkPassed = warpShrink <= 3.0 && weftShrink <= 3.0;
    const isPassed = isPointsPassed && isShrinkPassed;

    const certNumber = isPassed ? `COA-TXT-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}` : null;

    const newInsp: FabricQualityRecord = {
      id: `fqc-${Date.now()}`,
      inspectionReportCode: `FQC-RPT-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
      fabricRollBatchNumber: String(formData.get('rollBatch') || `TX-ROLL-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`),
      fabricType: String(formData.get('fabricType') || '100% Combed Cotton 40s Single Jersey'),
      inspectedLengthMeters: Number(formData.get('inspectedLength')) || 100.0,
      rollWidthInches: Number(formData.get('rollWidth')) || 60.0,
      pointsPer100SqYards: points,
      maxPermissiblePoints: maxPoints,
      measuredGsm: Number(formData.get('measuredGsm')) || 180.5,
      nominalGsm: Number(formData.get('nominalGsm')) || 180.0,
      warpDimensionalShrinkagePct: warpShrink,
      weftDimensionalShrinkagePct: weftShrink,
      colorFastnessWashingRating: Number(formData.get('fastnessWashing')) || 4.5,
      colorFastnessRubbingRating: Number(formData.get('fastnessRubbing')) || 4.0,
      astmD5430Grade: isPassed ? 'FIRST_QUALITY_PASS' : points > maxPoints ? 'REJECTED' : 'SECOND_QUALITY_REVERT',
      clearanceCertificateIssued: isPassed,
      clearanceCertificateNumber: certNumber,
      certifiedAt: isPassed ? 'Just now' : null,
      dispatchBlocked: !isPassed,
      inspectorNotes: String(formData.get('notes') || (isPassed ? 'ASTM D5430 4-point inspection passed. Certificate of Analysis issued.' : 'DISPATCH BLOCKED: Exceeded 4-point defect ceiling or dimensional shrinkage limit!')),
      createdAt: 'Just now',
    };

    setFabricInspections([newInsp, ...fabricInspections]);
    setIsNewFabricInspectionModal(false);
    if (isPassed) {
      showToast(`ASTM D5430 Inspection PASSED! Fabric CoA Certificate ${certNumber} issued.`);
    } else {
      showToast(`DISPATCH BLOCKED: Roll ${newInsp.fabricRollBatchNumber} failed 4-point test or shrinkage!`);
    }
  };

  const handleCertifyFabricInspection = (id: string) => {
    const certNumber = `COA-TXT-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;
    setFabricInspections(
      fabricInspections.map((f) => {
        if (f.id === id) {
          return {
            ...f,
            pointsPer100SqYards: Math.min(f.pointsPer100SqYards, 22.0),
            warpDimensionalShrinkagePct: Math.min(f.warpDimensionalShrinkagePct, 2.5),
            weftDimensionalShrinkagePct: Math.min(f.weftDimensionalShrinkagePct, 2.4),
            astmD5430Grade: 'FIRST_QUALITY_PASS',
            clearanceCertificateIssued: true,
            dispatchBlocked: false,
            clearanceCertificateNumber: certNumber,
            certifiedAt: 'Just now',
            inspectorNotes: 'Re-inspection after heat-setting and stenter relaxation completed. Certified compliant under ASTM D5430 4-point system.',
          };
        }
        return f;
      }),
    );
    showToast(`Fabric Quality Certificate ${certNumber} signed and approved! Dispatch gate unlocked.`);
  };

