  const handleAddHallmarkingQc = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const purityPct = Number(formData.get('xrfSpectrometerPurityPct')) || 75.2;
    const purityTested = String(formData.get('metalPurityTested') || '18K (750 Fine Gold)');
    const isPurityOk = purityTested.includes('22K') || purityTested.includes('916') ? purityPct >= 91.6 : purityPct >= 75.0;
    const laserVerified = formData.get('laserEngravingVerified') === 'yes';
    const isPassed = isPurityOk && laserVerified;
    const coaNumber = isPassed ? `COA-JWL-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}` : null;

    const newQc: JewelleryQcRecord = {
      id: `jqc-${Date.now()}`,
      qcReportNumber: `QC-JWL-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
      productSerialNumber: String(formData.get('productSerialNumber') || `APEX-JWL-${Math.floor(10000 + Math.random() * 90000)}`).toUpperCase(),
      itemDescription: String(formData.get('itemDescription') || 'Gold & Diamond Fine Jewellery'),
      grossWeightGrams: Number(formData.get('grossWeightGrams')) || 10.5,
      netGoldWeightGrams: Number(formData.get('netGoldWeightGrams')) || 10.0,
      metalPurityTested: purityTested,
      xrfSpectrometerPurityPct: purityPct,
      diamondCaratWeight: Number(formData.get('diamondCaratWeight')) || 0.0,
      diamondClarityGrade: String(formData.get('diamondClarityGrade') || 'VVS1'),
      diamondColorGrade: String(formData.get('diamondColorGrade') || 'E-Color (Colorless)'),
      diamondCutGrade: String(formData.get('diamondCutGrade') || 'Triple Excellent (3EX)'),
      gemstoneLabCertificationId: String(formData.get('gemstoneLabCertificationId') || '').trim() || null,
      bisHallmarkLaserHuid: String(formData.get('bisHallmarkLaserHuid') || `HUID-${Math.floor(100000 + Math.random() * 900000)}`).toUpperCase(),
      laserEngravingVerified: laserVerified,
      certificateOfAuthenticityNumber: coaNumber,
      coaIssuedAt: isPassed ? 'Just now' : null,
      certifiedByManager: isPassed ? 'GEMSTONE_HALLMARKING_QC_MANAGER' : null,
      qcStatus: !isPurityOk ? 'PURITY_FAIL' : !laserVerified ? 'HUID_PENDING' : 'PASSED',
      dispatchBlocked: !isPassed,
      inspectorRemarks: String(formData.get('inspectorRemarks') || (isPassed ? 'XRF spectrometry and BIS laser HUID verified compliant. CoA generated.' : 'DISPATCH BLOCKED: Failed purity threshold or laser hallmark verification!')),
      createdAt: 'Just now',
    };

    setJewelleryQcRecords([newQc, ...jewelleryQcRecords]);
    setIsNewJewelleryQcModal(false);
    if (isPassed) {
      showToast(`Hallmarking QC PASSED! Certificate of Authenticity ${coaNumber} generated.`);
    } else {
      showToast(`DISPATCH BLOCKED: Item ${newQc.productSerialNumber} failed purity/HUID gate!`);
    }
  };

