  const handleAddSplittingLog = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const targetMm = Number(formData.get('targetThicknessMm')) || 1.30;
    const tolMm = Number(formData.get('toleranceMm')) || 0.05;
    const p1 = Number(formData.get('point1ThicknessMm')) || targetMm;
    const p2 = Number(formData.get('point2ThicknessMm')) || targetMm;
    const p3 = Number(formData.get('point3ThicknessMm')) || targetMm;
    const p4 = Number(formData.get('point4ThicknessMm')) || targetMm;
    const p5 = Number(formData.get('point5ThicknessMm')) || targetMm;
    const avg = Number(((p1 + p2 + p3 + p4 + p5) / 5).toFixed(3));
    const maxDelta = Math.max(Math.abs(p1 - targetMm), Math.abs(p2 - targetMm), Math.abs(p3 - targetMm), Math.abs(p4 - targetMm), Math.abs(p5 - targetMm));
    const isUniform = maxDelta <= tolMm;

    const newSpl: SplittingShavingRecord = {
      id: `spl-${Date.now()}`,
      logNumber: `SPL-SHV-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
      machineId: String(formData.get('machineId') || 'Bandknife Splitting Machine #02 (Mosconi)'),
      bladeCalibrationStatus: (formData.get('bladeCalibrationStatus') as any) || 'CALIBRATED',
      bladeSharpnessIndex: Number(formData.get('bladeSharpnessIndex')) || 98.0,
      targetThicknessMm: targetMm,
      toleranceMm: tolMm,
      point1ThicknessMm: p1,
      point2ThicknessMm: p2,
      point3ThicknessMm: p3,
      point4ThicknessMm: p4,
      point5ThicknessMm: p5,
      averageThicknessMm: avg,
      thicknessUniformityStatus: isUniform ? 'UNIFORM' : 'OUT_OF_TOLERANCE',
      shavingWasteWeightKg: Number(formData.get('shavingWasteWeightKg')) || 80.0,
      hidesProcessed: Number(formData.get('hidesProcessed')) || 100,
      thicknessRangeCategory: String(formData.get('thicknessRangeCategory') || `${(targetMm - 0.1).toFixed(1)} - ${(targetMm + 0.1).toFixed(1)} mm Standard`),
      splitDropAction: (formData.get('splitDropAction') as any) || 'SUEDE_SPLIT_STAGED',
      status: isUniform ? 'INSPECTION_PASSED' : 'CALIBRATION_HOLD',
      operatorNotes: String(formData.get('operatorNotes') || '5-point thickness gauge calibrated across butt, bellies, and neck sampling points.'),
      createdAt: 'Just now',
    };

    setSplittingLogs([newSpl, ...splittingLogs]);
    setIsNewSplittingModal(false);
    showToast(`Splitting Log ${newSpl.logNumber} recorded (Avg: ${avg}mm, Uniformity: ${newSpl.thicknessUniformityStatus}).`);
  };

