    setCastingRecords([newCycle, ...castingRecords]);
    setIsNewCastingModal(false);
    showToast(`Casting cycle ${newCycle.castingTreeCode} logged (Yield: ${yieldPct}%, Unaccounted Loss: ${unaccounted}g).`);
