    const formData = new FormData(form);

    const issuedMetal = Number(formData.get('issuedMetalWeightGrams')) || 50.0;
    const receivedItem = Number(formData.get('receivedItemWeightGrams')) || 48.8;
    const scrapDust = Number(formData.get('returnedScrapDustGrams')) || 0.6;
    const allowedWastage = Number(formData.get('allowedWastageGrams')) || 0.8;
