  const handleAddMilkCollection = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const formData = new FormData(form);

    const gross = Number(formData.get('grossWeightKg')) || 24000.0;
    const tare = Number(formData.get('tareWeightKg')) || 9000.0;
    const net = gross - tare;
    const density = Number(formData.get('milkDensity')) || 1.03;
    const netVol = Number((net / density).toFixed(1));
    const rate = Number(formData.get('ratePerLiterInr')) || 42.5;
    const totalPayment = Number((netVol * rate).toFixed(2));
    const fat = Number(formData.get('fatPercentage')) || 4.2;
    const snf = Number(formData.get('snfPercentage')) || 8.6;
    const temp = Number(formData.get('milkTemperatureCelsius')) || 4.0;
    const isQualityPass = fat >= 3.5 && snf >= 8.5 && temp <= 4.5;

    const newRecord: MilkCollectionRecord = {
      id: `milk-rec-${Date.now()}`,
      collectionCode: `MILK-REC-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
      tankerRegistrationNumber: String(formData.get('tankerRegistrationNumber') || 'GJ-01-DK-9412'),
      supplierOrFarmerGroup: String(formData.get('supplierOrFarmerGroup') || 'Anand Dairy Producers Co-operative'),
      driverName: String(formData.get('driverName') || 'Ramesh Patel'),
      grossWeightKg: gross,
      tareWeightKg: tare,
      netWeightKg: net,
      netVolumeLiters: netVol,
      fatPercentage: fat,
      snfPercentage: snf,
      addedWaterPercentage: Number(formData.get('addedWaterPercentage')) || 0.0,
      milkDensity: density,
      milkTemperatureCelsius: temp,
      paymentGradeStatus: isQualityPass ? 'GRADE_A_PREMIUM' : 'GRADE_B_STANDARD',
      ratePerLiterInr: rate,
      totalPaymentInr: totalPayment,
      chillingSiloId: String(formData.get('chillingSiloId') || 'RAW-SILO-01 (Capacity: 50,000L)'),
      siloTemperatureCelsius: Number(formData.get('siloTemperatureCelsius')) || 3.4,
      status: 'CHILLED_STAGED',
      operatorNotes: String(formData.get('operatorNotes') || 'Weighbridge gross/tare and ultrasonic analyzer Fat/SNF verified.'),
      createdAt: 'Just now',
    };

    setMilkCollections([newRecord, ...milkCollections]);
    setIsNewMilkCollectionModal(false);
    showToast(`Milk Intake ${newRecord.collectionCode} logged: ${newRecord.netVolumeLiters} L (Fat ${newRecord.fatPercentage}%, SNF ${newRecord.snfPercentage}%).`);
  };

